describe('Particle.destroy', () => {
  let particle;

  beforeEach(() => {
    // Reset mocks
    jest.clearAllMocks();

    // Create particle with proper mock setup
    particle = new Particle();
    particle.removeAllBehaviours = jest.fn();
    particle.energy = 1;
    particle.dead = false;
    particle.parent = {};
  });

  test('should call removeAllBehaviours method', () => {
    particle.destroy();
    expect(particle.removeAllBehaviours).toHaveBeenCalledTimes(1);
  });

  test('should set energy to 0', () => {
    particle.destroy();
    expect(particle.energy).toBe(0);
  });

  test('should set dead to true', () => {
    particle.destroy();
    expect(particle.dead).toBe(true);
  });

  test('should set parent to null', () => {
    particle.destroy();
    expect(particle.parent).toBeNull();
  });

  test('should properly destroy particle with all properties set', () => {
    // Setup particle with some values
    particle.energy = 100;
    particle.dead = false;
    particle.parent = { id: 'parent-id' };
    particle.behaviours = [{}, {}];

    particle.destroy();

    expect(particle.removeAllBehaviours).toHaveBeenCalled();
    expect(particle.energy).toBe(0);
    expect(particle.dead).toBe(true);
    expect(particle.parent).toBeNull();
  });
});

