import RandomDrift from '../../../src/behaviour/RandomDrift';
import Vector2D from '../../../src/math/Vector2D';

jest.mock('../../../src/math/Vector2D');

describe('RandomDrift', () => {
  describe('reset', () => {
    let randomDrift;

    beforeEach(() => {
      Vector2D.mockImplementation((x, y) => ({
        x,
        y,
        multiplyScalar: jest.fn()
      }));

      randomDrift = new RandomDrift(1, 0, 100, 1000, 'ease');
      randomDrift.normalizeForce = jest.fn().mockImplementation((force) => {
        force.multiplyScalar.mockReturnValue({ x: force.x, y: force.y });
        return force;
      });
    });

    it('should create a new Vector2D with driftX and driftY parameters', () => {
      randomDrift.reset(2, 3, 200);

      expect(Vector2D).toHaveBeenCalledWith(2, 3);
    });

    it('should normalize the pan force vector', () => {
      const driftX = 5;
      const driftY = 10;

      randomDrift.reset(driftX, driftY, 300);

      expect(randomDrift.normalizeForce).toHaveBeenCalledWith(expect.objectContaining({ x: driftX, y: driftY }));
    });

    it('should set the delay property', () => {
      const delay = 500;

      randomDrift.reset(1, 0, delay);

      expect(randomDrift.delay).toBe(delay);
    });

    it('should call super.reset when life parameter is provided', () => {
      const life = 2000;
      const easing = 'linear';
      const superResetSpy = jest.spyOn(Object.getPrototypeOf(randomDrift), 'reset');
      superResetSpy.mockClear();

      randomDrift.reset(1, 0, 100, life, easing);

      expect(superResetSpy).toHaveBeenCalledWith(life, easing);
    });

    it('should not call super.reset when life parameter is not provided', () => {
      const superResetSpy = jest.spyOn(Object.getPrototypeOf(randomDrift), 'reset');
      superResetSpy.mockClear();

      randomDrift.reset(1, 0, 100);

      expect(superResetSpy).not.toHaveBeenCalled();
    });

    it('should update panFoce with normalized vector', () => {
      const result = { x: 1, y: 0 };
      randomDrift.normalizeForce = jest.fn().mockReturnValue(result);

      randomDrift.reset(3, 4, 150);

      expect(randomDrift.panFoce).toBe(result);
    });
  });
});

