    mockContainer = {
      parentNode: true
    };
    const mockRemoveChild = jest.fn();
    mockBody = {
      removeChild: mockRemoveChild
    };

    stats.container = mockContainer;
    stats.body = mockBody;

    stats.destroy();

    expect(mockRemoveChild).toHaveBeenCalledWith(mockContainer);
    expect(stats.proton).toBeNull();
    expect(stats.container).toBeNull();
  });

  test('should use document.body when body is not defined but container has parent', () => {
    mockContainer = {
      parentNode: true
    };
    const mockRemoveChild = jest.fn();
    const originalBody = document.body;

    // Mock document.body
    Object.defineProperty(document, 'body', {
      value: { removeChild: mockRemoveChild },
      writable: true
    });

    stats.container = mockContainer;

    stats.destroy();

    expect(mockRemoveChild).toHaveBeenCalledWith(mockContainer);
    expect(stats.proton).toBeNull();
    expect(stats.container).toBeNull();

    // Restore original document.body
    Object.defineProperty(document, 'body', {
      value: originalBody,
      writable: true
    });
  });

  test('should not attempt to remove container when container is null', () => {
    stats.container = null;

    stats.destroy();

    expect(stats.proton).toBeNull();
    expect(stats.container).toBeNull();
  });

  test('should not attempt to remove container when container has no parent node', () => {
    mockContainer = {
      parentNode: null
    };
    stats.container = mockContainer;

    stats.destroy();

    expect(stats.proton).toBeNull();
    expect(stats.container).toBeNull();
  });

