    beforeEach(() => {
      randomDrift = new RandomDrift(10, 5, 100, 1000, null);

      mockParticleA = {
        addXY: jest.fn()
      };

      mockParticleData = {
        time: 0
      };

      particle = {
        a: mockParticleA,
        data: mockParticleData
      };
    });

    it('should increment particle data time', () => {
      const initialTime = 50;
      particle.data.time = initialTime;

      randomDrift.applyBehaviour(particle, 25, 0);

      expect(particle.data.time).toBe(initialTime + 25);
    });

    it('should not apply drift when time is less than delay', () => {
      randomDrift.delay = 100;
      particle.data.time = 50;

      randomDrift.applyBehaviour(particle, 30, 0);

      expect(mockParticleA.addXY).not.toHaveBeenCalled();
      expect(particle.data.time).toBe(80);
    });

    it('should apply drift when time reaches delay threshold', () => {
      MathUtil.randomAToB.mockImplementation((min, max) => (min + max) / 2);

      randomDrift.panFoce = { x: 10, y: 5 };
      randomDrift.delay = 100;
      particle.data.time = 75;

      randomDrift.applyBehaviour(particle, 25, 0);

      expect(MathUtil.randomAToB).toHaveBeenCalledWith(-10, 10);
      expect(MathUtil.randomAToB).toHaveBeenCalledWith(-5, 5);
      expect(mockParticleA.addXY).toHaveBeenCalledWith(0, 0);
      expect(particle.data.time).toBe(0);
    });

    it('should apply drift with correct random values', () => {
      MathUtil.randomAToB.mockImplementationOnce(() => 3.5);
      MathUtil.randomAToB.mockImplementationOnce(() => -1.2);

      randomDrift.panFoce = { x: 8, y: 4 };
      randomDrift.delay = 50;
      particle.data.time = 50;

      randomDrift.applyBehaviour(particle, 10, 0);

      expect(mockParticleA.addXY).toHaveBeenCalledWith(3.5, -1.2);
      expect(particle.data.time).toBe(0);
    });

    it('should handle multiple calls correctly', () => {
      MathUtil.randomAToB.mockImplementation((min, max) => min);

      randomDrift.panFoce = { x: 6, y: 3 };
      randomDrift.delay = 30;

      // First call - not enough time
      randomDrift.applyBehaviour(particle, 20, 0);
      expect(mockParticleA.addXY).not.toHaveBeenCalled();
      expect(particle.data.time).toBe(20);

      // Second call - enough time accumulated
      randomDrift.applyBehaviour(particle, 15, 0);
      expect(mockParticleA.addXY).toHaveBeenCalledWith(-6, -3);
      expect(particle.data.time).toBe(0);
    });
  });
});

