describe('PixelRenderer', () => {
  describe('resize', () => {
    let canvas;
    let pixelRenderer;
    let mockRectangle;
    let mockContext;

    beforeEach(() => {
      // Create a mock canvas element
      canvas = document.createElement('canvas');
      mockRectangle = { x: 0, y: 0, width: 100, height: 100 };

      // Mock the context with required methods
      mockContext = {
        createImageData: jest.fn(),
        putImageData: jest.fn(),
        fillRect: jest.fn(),
        clearRect: jest.fn()
      };

      // Mock the getContext method to return our mock context
      canvas.getContext = jest.fn().mockReturnValue(mockContext);

      // Mock createImageData to prevent errors during construction
      mockContext.createImageData.mockReturnValue({
        data: new Uint8ClampedArray(100 * 100 * 4)
      });

      pixelRenderer = new PixelRenderer(canvas, mockRectangle);
    });

    it('should set the canvas width and height', () => {
      const newWidth = 200;
      const newHeight = 150;

      pixelRenderer.resize(newWidth, newHeight);

      expect(canvas.width).toBe(newWidth);
      expect(canvas.height).toBe(newHeight);
    });

    it('should handle zero dimensions', () => {
      pixelRenderer.resize(0, 0);

      expect(canvas.width).toBe(0);
      expect(canvas.height).toBe(0);
    });

    it('should handle negative dimensions', () => {
      const originalWidth = canvas.width;
      const originalHeight = canvas.height;

      pixelRenderer.resize(-100, -50);

      // Canvas elements convert negative values to positive
