      expect(canvas.width).toBeGreaterThanOrEqual(0);
      expect(canvas.height).toBeGreaterThanOrEqual(0);
    });

    it('should handle floating point dimensions', () => {
      // Canvas elements truncate floating point values
      pixelRenderer.resize(100.5, 200.7);

      // Verify that the values are converted as the browser would
      expect(Number.isInteger(canvas.width)).toBe(true);
      expect(Number.isInteger(canvas.height)).toBe(true);
    });
  });
});

