describe('Color', () => {
  describe('applyBehaviour', () => {
    let colorBehaviour;
    let particle;
    let time;
    let index;

    beforeEach(() => {
      // Create a Color behaviour instance
      colorBehaviour = new Color(
        { r: 255, g: 0, b: 0 }, // a - red
        { r: 0, g: 0, b: 255 }, // b - blue
        1000, // life
        null // easing
      );

      // Create a mock particle
      particle = {
        rgb: { r: 0, g: 0, b: 0 },
        data: {
          colorA: { r: 255, g: 0, b: 0 },
          colorB: { r: 0, g: 0, b: 255 }
        }
      };

      time = 500; // midpoint
      index = 0;
    });

    it('should interpolate colors when b is defined', () => {
      // Mock calculate to set energy to 0.5 (midpoint)
      colorBehaviour.calculate = jest.fn((p, t, i) => {
        colorBehaviour.energy = 0.5;
      });

      colorBehaviour.applyBehaviour(particle, time, index);

      // At midpoint, we expect middle values between red (255,0,0) and blue (0,0,255)
      // r: 0 + (255 - 0) * 0.5 = 127.5 -> 127 (after bitwise operation)
      // g: 0 + (0 - 0) * 0.5 = 0
      // b: 255 + (0 - 255) * 0.5 = 127.5 -> 127 (after bitwise operation)
      expect(particle.rgb.r).toBe(127);
      expect(particle.rgb.g).toBe(0);
      expect(particle.rgb.b).toBe(127);
    });

    it('should use colorA directly when b is not defined', () => {
      // Create a Color behaviour without b parameter
      const colorBehaviourWithoutB = new Color(
        { r: 255, g: 0, b: 0 }, // a - red
        null, // b - null
        1000, // life
        null // easing
      );

      colorBehaviourWithoutB.applyBehaviour(particle, time, index);

      // Should directly use colorA values
      expect(particle.rgb.r).toBe(255);
      expect(particle.rgb.g).toBe(0);
      expect(particle.rgb.b).toBe(0);
    });

    it('should handle different energy values correctly', () => {
      // Test with energy = 0 (should be all colorB)
      colorBehaviour.calculate = jest.fn((p, t, i) => {
        colorBehaviour.energy = 0;
      });

      colorBehaviour.applyBehaviour(particle, time, index);

      expect(particle.rgb.r).toBe(0);
      expect(particle.rgb.g).toBe(0);
      expect(particle.rgb.b).toBe(255);

      // Reset particle
      particle.rgb = { r: 0, g: 0, b: 0 };

      // Test with energy = 1 (should be all colorA)
      colorBehaviour.calculate = jest.fn((p, t, i) => {
        colorBehaviour.energy = 1;
      });

      colorBehaviour.applyBehaviour(particle, time, index);

      expect(particle.rgb.r).toBe(255);
      expect(particle.rgb.g).toBe(0);
      expect(particle.rgb.b).toBe(0);
    });

    it('should perform bitwise operations correctly', () => {
      // Test that decimal values are properly truncated
      colorBehaviour.calculate = jest.fn((p, t, i) => {
        colorBehaviour.energy = 0.3;
      });

      colorBehaviour.applyBehaviour(particle, time, index);

      // Values should be truncated, not rounded
      // r: 0 + (255 - 0) * 0.3 = 76.5 -> 76
      // g: 0 + (0 - 0) * 0.3 = 0
      // b: 255 + (0 - 255) * 0.3 = 178.5 -> 178
      expect(particle.rgb.r).toBe(76);
      expect(particle.rgb.g).toBe(0);
      expect(particle.rgb.b).toBe(178);
    });
  });
});

